  1	export interface Customer {
  2	  yearsWithMHPCO: number;
  3	}
  4	
  5	export interface Item {
  6	  type: string;
  7	  material?: string;
  8	  enchantment?: number;
  9	  cursed?: boolean;
 10	}
 11	
 12	const PROCESSING_FEE = 5;
 13	const DEDUCTIBLE = 100;
 14	const CAP_MULTIPLIER = 2;
 15	const REDUCED_REIMBURSEMENT_LEVEL = 8;
 16	const REDUCED_REIMBURSEMENT_RATE = 0.5;
 17	
 18	const INSURANCE_VALUES: Record<string, number> = {
 19	  sword: 1000,
 20	  amulet: 600,
 21	  staff: 800,
 22	  potion: 400,
 23	  rune: 250,
 24	  moonstone: 250,
 25	};
 26	
 27	const BASE_PREMIUMS: Record<string, number> = {
 28	  sword: 100,
 29	  amulet: 60,
 30	  staff: 80,
 31	  potion: 40,
 32	  rune: 25,
 33	  moonstone: 25,
 34	};
 35	
 36	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
 37	const BLOCK_SIZE = 3;
 38	const BLOCK_BASE_PREMIUM = 60;
 39	const CURSE_SURCHARGE_RATE = 0.5;
 40	const HIGH_ENCHANTMENT_LEVEL = 5;
 41	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
 42	const LOYALTY_YEARS = 2;
 43	const LOYALTY_DISCOUNT_RATE = 0.2;
 44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
 45	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
 46	
 47	function basePremiumFor(type: string): number {
 48	  const premium = BASE_PREMIUMS[type];
 49	  if (premium === undefined) {
 50	    throw new Error(`MHPCO does not insure items of type "${type}"`);
 51	  }
 52	  return premium;
 53	}
 54	
 55	function isComponent(type: string): boolean {
 56	  return COMPONENT_TYPES.has(type);
 57	}
 58	
 59	function groupByType(items: Item[]): Map<string, Item[]> {
 60	  const groups = new Map<string, Item[]>();
 61	  for (const item of items) {
 62	    const group = groups.get(item.type) ?? [];
 63	    group.push(item);
 64	    groups.set(item.type, group);
 65	  }
 66	  return groups;
 67	}
 68	
 69	function groupBasePremium(type: string, group: Item[]): number {
 70	  const perItem = basePremiumFor(type);
 71	  if (isComponent(type) && group.length === BLOCK_SIZE) {
 72	    return BLOCK_BASE_PREMIUM;
 73	  }
 74	  return group.length * perItem;
 75	}
 76	
 77	function isCursed(item: Item): boolean {
 78	  return item.cursed === true;
 79	}
 80	
 81	function isHighlyEnchanted(item: Item): boolean {
 82	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
 83	}
 84	
 85	function riskSurcharge(item: Item): number {
 86	  const base = basePremiumFor(item.type);
 87	  const curse = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
 88	  const enchantment = isHighlyEnchanted(item)
 89	    ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE
 90	    : 0;
 91	  return curse + enchantment;
 92	}
 93	
 94	function policyBasePremium(items: Item[]): number {
 95	  let total = 0;
 96	  for (const [type, group] of groupByType(items)) {
 97	    total += groupBasePremium(type, group);
 98	  }
 99	  return total;
100	}
101	
102	function itemRiskSurcharges(items: Item[]): number {
103	  return items.reduce((total, item) => total + riskSurcharge(item), 0);
104	}
105	
106	function isLongStanding(customer: Customer): boolean {
107	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
108	}
109	
110	function isFollowUpContract(previousContracts: number): boolean {
111	  return previousContracts > 0;
112	}
113	
114	function customerAdjustments(
115	  customer: Customer,
116	  basePremium: number,
117	  previousContracts: number,
118	): number {
119	  const loyalty = isLongStanding(customer) ? -basePremium * LOYALTY_DISCOUNT_RATE : 0;
120	  const firstInsurance = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
121	  const followUp = isFollowUpContract(previousContracts)
122	    ? -basePremium * FOLLOW_UP_DISCOUNT_RATE
123	    : 0;
124	  return loyalty + firstInsurance + followUp;
125	}
126	
127	function roundPremiumInMhpcoFavour(premium: number): number {
128	  return Math.ceil(premium);
129	}
130	
131	export function quote(customer: Customer, items: Item[], previousContracts = 0): number {
132	  const basePremium = policyBasePremium(items);
133	  const premium =
134	    basePremium +
135	    itemRiskSurcharges(items) +
136	    customerAdjustments(customer, basePremium, previousContracts) +
137	    PROCESSING_FEE;
138	  return roundPremiumInMhpcoFavour(premium);
139	}
140	
141	export interface QuoteStep {
142	  op: "quote";
143	  items: Item[];
144	}
145	
146	export interface Damage {
147	  itemType: string;
148	  amount: number;
149	}
150	
151	export interface Incident {
152	  cause: string;
153	  damages: Damage[];
154	}
155	
156	export interface ClaimStep {
157	  op: "claim";
158	  policy: number;
159	  incident: Incident;
160	}
161	
162	export type Step = QuoteStep | ClaimStep;
163	
164	export interface Scenario {
165	  customer: Customer;
166	  steps: Step[];
167	}
168	
169	export interface QuoteResult {
170	  premium: number;
171	}
172	
173	export interface ClaimResult {
174	  payout: number;
175	  remainingCap: number;
176	}
177	
178	export type StepResult = QuoteResult | ClaimResult;
179	
180	interface Policy {
181	  items: Item[];
182	  remainingCap: number;
183	}
184	
185	function insuranceSum(items: Item[]): number {
186	  return items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
187	}
188	
189	function isDangerouslyEnchanted(item: Item): boolean {
190	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_LEVEL;
191	}
192	
193	// MHPCO's clauses: enchantment >= 8 halves the reimbursement and takes
194	// precedence; dragon material is reimbursed in full, which is also the
195	// reimbursement for an item to which no special clause applies.
196	function reimbursement(item: Item, amount: number): number {
197	  return isDangerouslyEnchanted(item) ? amount * REDUCED_REIMBURSEMENT_RATE : amount;
198	}
199	
200	function payoutFor(item: Item, damage: Damage): number {
201	  return Math.max(0, reimbursement(item, damage.amount) - DEDUCTIBLE);
202	}
203	
204	function roundPayoutInMhpcoFavour(payout: number): number {
205	  return Math.floor(payout);
206	}
207	
208	interface DamagedItem {
209	  item: Item;
210	  damage: Damage;
211	}
212	
213	// Each damage entry refers to one insured item, so an item already damaged by
214	// an earlier entry of the same incident cannot answer for a later one.
215	function allocateDamagedItems(policy: Policy, damages: Damage[]): DamagedItem[] {
216	  const unclaimed = [...policy.items];
217	  return damages.map((damage) => {
218	    const index = unclaimed.findIndex((insured) => insured.type === damage.itemType);
219	    if (index === -1) {
220	      throw new Error(`The policy does not cover an item of type "${damage.itemType}"`);
221	    }
222	    return { item: unclaimed.splice(index, 1)[0], damage };
223	  });
224	}
225	
226	function rejectInvalidDamageReports(damages: Damage[]): void {
227	  for (const damage of damages) {
228	    if (damage.amount < 0) {
229	      throw new Error(`A damage amount cannot be negative: ${damage.amount}`);
230	    }
231	  }
232	}
233	
234	function desiredPayout(policy: Policy, incident: Incident): number {
235	  return allocateDamagedItems(policy, incident.damages).reduce(
236	    (total, { item, damage }) => total + payoutFor(item, damage),
237	    0,
238	  );
239	}
240	
241	function limitToRemainingCap(desired: number, remainingCap: number): number {
242	  return Math.min(desired, remainingCap);
243	}
244	
245	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
246	  rejectInvalidDamageReports(incident.damages);
247	  const granted = limitToRemainingCap(desiredPayout(policy, incident), policy.remainingCap);
248	  const payout = roundPayoutInMhpcoFavour(granted);
249	  policy.remainingCap -= payout;
250	  return { payout, remainingCap: policy.remainingCap };
251	}
252	
253	export function runScenario(scenario: Scenario): StepResult[] {
254	  const policies = new Map<number, Policy>();
255	  let contracts = 0;
256	
257	  return scenario.steps.map((step, index) => {
258	    if (step.op === "quote") {
259	      const premium = quote(scenario.customer, step.items, contracts);
260	      contracts += 1;
261	      policies.set(index, {
262	        items: step.items,
263	        remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
264	      });
265	      return { premium };
266	    }
267	
268	    const policy = policies.get(step.policy);
269	    if (policy === undefined) {
270	      throw new Error(`Step ${step.policy} did not create a policy`);
271	    }
272	    return settleClaim(policy, step.incident);
273	  });
274	}

